                    :date-format-options="{ year: 'numeric', month: '2-digit', day: '2-digit' }"
                  ></b-form-datepicker>
                </b-form-group>
              </b-col>
              <b-col cols="auto" class="mb-2 mb-lg-0">
                <b-button
                  size="sm"
                  variant="success"
                  @click="refreshData()"
                >
                  <b-icon icon="search" class="mr-1"></b-icon>
                  Buscar
                </b-button>
              </b-col>
              <b-col class="text-right mb-2 mb-lg-0">
                <b-button
                  size="sm"
                  variant="outline-success"
                  class="mr-1"
                  @click="generatePaymentExcel()"
                  :disabled="tranzactions.length === 0"
                >
                  <b-icon icon="file-earmark-spreadsheet" class="mr-1"></b-icon>
                  Pagamentos
                </b-button>
                <b-button
                  size="sm"
                  variant="success"
                  class="mr-1"
                  @click="generateExcelReport()"
                  :disabled="disbursedLoan.length === 0"
                >
                  <b-icon icon="file-earmark-spreadsheet" class="mr-1"></b-icon>
                  Relatório BM
                </b-button>
                <b-button
                  size="sm"
                  variant="outline-primary"
                  @click="generatePDFReport()"
                  :disabled="disbursedLoan.length === 0"
                >
                  <b-icon icon="printer-fill" class="mr-1"></b-icon>
                  PDF
                </b-button>
              </b-col>
            </b-row>
          </b-card-body>
        </b-card>

        <!-- ===================== CRÉDITOS DESEMBOLSADOS (INTERVALO) ===================== -->
        <b-card class="report-card mb-3" no-body>
          <b-card-header class="report-header report-header-primary">
            <b-icon icon="cash-stack" class="mr-2"></b-icon>
            Créditos Desembolsados
            <b-badge variant="light" pill class="ml-2 text-dark">{{ disbursedLoan.length }}</b-badge>
            <span class="report-period ml-3">{{ getRangePeriodLabel() }}</span>
          </b-card-header>
          <b-card-body class="p-0">
            <b-overlay :show="isLoading" rounded="sm">

              <!-- Resumo KPIs -->
              <div v-if="disbursedLoan.length > 0" class="kpi-strip px-3 py-2">
                <div class="kpi-item">
                  <span class="kpi-label">Total Desembolsado</span>
                  <span class="kpi-value text-primary">{{ convertMoney(getSummaryTotalCapital()) }}</span>
                </div>
                <div class="kpi-item">
                  <span class="kpi-label">Total c/ Juros</span>
                  <span class="kpi-value text-success">{{ convertMoney(getSummaryTotalWithInterest()) }}</span>
                </div>
                <div class="kpi-item">
                  <span class="kpi-label">Nº de Créditos</span>
                  <span class="kpi-value">{{ disbursedLoan.length }}</span>
                </div>
                <div class="kpi-item">
                  <span class="kpi-label">Total de Prestações</span>
                  <span class="kpi-value">{{ getSummaryTotalInstallments() }}</span>
                </div>
              </div>

              <div class="table-responsive" v-if="disbursedLoan.length > 0">
                <table class="table table-sm table-hover table-bordered report-table mb-0">
                  <thead>
                    <tr class="table-header-row">
                      <th class="align-middle text-center" style="width: 40px">#</th>
                      <th class="align-middle">Nome do Cliente</th>
                      <th class="align-middle text-center">Nº Conta</th>
                      <th class="align-middle text-right">Capital (MZN)</th>
                      <th class="align-middle text-center">Taxa (%)</th>
                      <th class="align-middle text-right">Valor Prestação (MZN)</th>
                      <th class="align-middle text-center">Nº Prestações</th>
                      <th class="align-middle text-right">Total c/ Juros (MZN)</th>
                      <th class="align-middle text-center">1ª Prestação</th>
                      <th class="align-middle text-center">Última Prestação</th>
                      <th class="align-middle text-center">Data Desembolso</th>
                    </tr>
                  </thead>
                  <tbody>
                    <tr
                      v-for="(loan, idx) in disbursedLoan"
                      :key="'range-' + loan.id"
                      class="data-row"
                    >
                      <td class="text-center">{{ idx + 1 }}</td>
                      <td>{{ getCustomerDetails(loan.accountNumber).customerName }}</td>
                      <td class="text-center">{{ loan.accountNumber }}</td>
                      <td class="text-right">{{ convertMoney(loan.amount) }}</td>
                      <td class="text-center">{{ formatPercentage(loan.interestRate) }}</td>
                      <td class="text-right">{{ convertMoney(getMonthlyInstallment(loan)) }}</td>
                      <td class="text-center">{{ loan.numberOfInstallments || 1 }}</td>
                      <td class="text-right font-weight-bold">{{ convertMoney(getTotalWithInterest(loan)) }}</td>
                      <td class="text-center">{{ formatDate(getFirstInstallmentDate(loan)) }}</td>
                      <td class="text-center">{{ formatDate(getLastInstallmentDate(loan)) }}</td>
                      <td class="text-center" v-date-format="loan.dateCreated"></td>
                    </tr>
                  </tbody>
                  <tfoot>
                    <tr class="totals-row">
                      <td colspan="3" class="text-right font-weight-bold">Totais</td>
                      <td class="text-right font-weight-bold">{{ convertMoney(getSummaryTotalCapital()) }}</td>
                      <td></td>
                      <td class="text-right font-weight-bold">{{ convertMoney(getSummaryTotalMonthlyInstallment()) }}</td>
                      <td class="text-center font-weight-bold">{{ getSummaryTotalInstallments() }}</td>
                      <td class="text-right font-weight-bold">{{ convertMoney(getSummaryTotalWithInterest()) }}</td>
                      <td colspan="3"></td>
                    </tr>
                  </tfoot>
                </table>
              </div>

              <b-alert
                class="text-center m-3"
                v-if="disbursedLoan.length === 0"
                variant="info"
                show
              >
                <b-icon icon="search" class="mr-1"></b-icon>
                Seleccione um intervalo de datas e clique em "Buscar" para listar os créditos desembolsados.
              </b-alert>

            </b-overlay>
          </b-card-body>
        </b-card>

        <!-- ===================== TABELA DO RELATÓRIO BM ===================== -->
        <b-card class="report-card mb-3" no-body>
          <b-card-header class="report-header">
            <b-icon icon="table" class="mr-2"></b-icon>
            Relatório Mensal de Créditos Desembolsados
            <b-badge variant="secondary" pill class="ml-2">{{ disbursedLoan.length }}</b-badge>
            <span class="report-period ml-3">Período: {{ getReportPeriodLabel() }}</span>
          </b-card-header>
          <b-card-body class="p-0">
            <b-overlay :show="isLoading" rounded="sm">

              <div class="table-responsive" v-if="disbursedLoan.length > 0">
                <table class="table table-sm table-hover table-bordered report-table mb-0">
                  <thead>
                    <tr class="table-header-row">
                      <th rowspan="2" class="align-middle text-center col-narrow">Nº da Operação (1)</th>
                      <th rowspan="2" class="align-middle">Nome do Cliente (2)</th>
                      <th rowspan="2" class="align-middle text-center">Data de Desembolso (3)</th>
                      <th rowspan="2" class="align-middle text-right">Montante de Desembolso (4)</th>
                      <th rowspan="2" class="align-middle text-center">Finalidade do Crédito (5)</th>
                      <th rowspan="2" class="align-middle text-right">Valor da Prestação (6)</th>
                      <th rowspan="2" class="align-middle text-center">Periodicidade dos Pagamentos (7)</th>
                      <th rowspan="2" class="align-middle text-center">Prazo de Reembolso (8)</th>
                      <th rowspan="2" class="align-middle text-center col-narrow">Taxa de Juro (9)</th>
                      <th rowspan="2" class="align-middle text-right">Crédito em Dívida (10)</th>
                      <th rowspan="2" class="align-middle text-right">Crédito em Atraso (11)</th>
                      <th rowspan="2" class="align-middle text-center col-narrow">Dias em Atraso (12)</th>
                      <th rowspan="2" class="align-middle text-center col-narrow">PPEs (13)</th>
                    </tr>
                  </thead>
                  <tbody>
                    <tr
                      v-for="loan in disbursedLoan"
                      :key="loan.id"
                      class="data-row"
                    >
                      <td class="text-center">{{ loan.id }}</td>
                      <td>{{ getCustomerDetails(loan.accountNumber).customerName }}</td>
                      <td class="text-center" v-date-format="loan.dateCreated"></td>
                      <td class="text-right" v-money-format="loan.amount"></td>
                      <td class="text-center">Comércio</td>
                      <td class="text-right">{{ convertMoney(getInstallmentValue(loan)) }}</td>
                      <td class="text-center">Mensal</td>
                      <td class="text-center" v-date-format="getDueDate(loan)"></td>
                      <td class="text-center">{{ getRate(loan.interestRate) }}</td>
                      <td class="text-right">{{ convertMoney(getCreditoEmDivida(loan)) }}</td>
                      <td class="text-right">{{ convertMoney(getCreditoEmAtraso(loan)) }}</td>
                      <td class="text-center">{{ lateDays(loan) > 0 ? lateDays(loan) : '' }}</td>
                      <td class="text-center"></td>
                    </tr>
                  </tbody>
                  <tfoot>
                    <tr class="totals-row">
                      <td colspan="3" class="text-right font-weight-bold">Total</td>
                      <td class="text-right font-weight-bold">{{ convertMoney(getTotalDesembolsado()) }}</td>
                      <td></td>
                      <td class="text-right font-weight-bold">{{ convertMoney(getTotalPrestacao()) }}</td>
                      <td colspan="3"></td>
                      <td class="text-right font-weight-bold">{{ convertMoney(getTotalDivida()) }}</td>
                      <td class="text-right font-weight-bold">{{ convertMoney(getTotalAtraso()) }}</td>
                      <td colspan="2"></td>
                    </tr>
                  </tfoot>
                </table>
              </div>

              <!-- Sem dados -->
              <b-alert
                class="text-center m-3"
                v-if="disbursedLoan.length === 0"
                variant="warning"
                show
              >
                <b-icon icon="exclamation-circle-fill" class="mr-1"></b-icon>
                Sem créditos desembolsados no período seleccionado.
              </b-alert>

            </b-overlay>
          </b-card-body>
        </b-card>

        <!-- ===================== NOTAS EXPLICATIVAS ===================== -->
        <b-card
          class="notes-card mb-3"
          no-body
          v-if="disbursedLoan.length > 0"
        >
          <b-card-header class="notes-header">
            <b-icon icon="info-circle" class="mr-2"></b-icon>
            Notas Explicativas
          </b-card-header>
          <b-card-body class="py-2 px-3">
            <div class="notes-grid">
              <div class="note-item"><strong>1</strong> - Número da operação de crédito</div>
              <div class="note-item"><strong>2</strong> - Nome do cliente</div>
              <div class="note-item"><strong>3</strong> - Data do desembolso inicial</div>
              <div class="note-item"><strong>4</strong> - Valor do crédito concedido</div>
              <div class="note-item"><strong>5</strong> - Finalidade de crédito desembolsado, designadamente para empresas, consumo ou habitação</div>
              <div class="note-item"><strong>6</strong> - Montante da prestação periódica para amortizar o crédito</div>
              <div class="note-item"><strong>7</strong> - Forma de pagamento acordada, designadamente diária, semanal, mensal ou anual</div>
              <div class="note-item"><strong>8</strong> - Data de vencimento do crédito desembolsado</div>
              <div class="note-item"><strong>9</strong> - Percentagem da taxa de juro aplicada a crédito</div>
              <div class="note-item"><strong>10</strong> - Montante do crédito desembolsado que falta pagar, excluindo prestações em atraso</div>
              <div class="note-item"><strong>11</strong> - Montante das prestações em atraso incluindo capital e juros</div>
              <div class="note-item"><strong>12</strong> - Dias em atraso do pagamento das prestações</div>
              <div class="note-item"><strong>13</strong> - Crédito concedido a pessoas politicamente expostas</div>
            </div>
          </b-card-body>
        </b-card>

      </div>
    </b-container>
