</template>

<script>
import { mapGetters } from "vuex";

import NavBarVue from "@/components/NavBar";
import moment from "moment";
import axios from "axios";
import MoneyFormat from "@/utils/moneyFormat";
import DateFormat from "@/utils/dateFormat";
import bmLogo from "@/utils/getBMLogo";
import pdfMake from "pdfmake/build/pdfmake";
import pdfFonts from "pdfmake/build/vfs_fonts";
pdfMake.vfs = pdfFonts.pdfMake.vfs;
import * as XLSX from "xlsx";

export default {
  data: () => ({
    fromDate: moment().startOf("month").format("YYYY-MM-DD"),
    toDate: moment().format("YYYY-MM-DD"),

    selectedPaymentMethod: 0,

    options: [
      { value: 0, text: "Meio de pagamento" },
      { value: 1, text: "Boca de Caixa" },
      { value: 2, text: "Depósito Bancário" },
      { value: 3, text: "Transferência Bancária" },
      { value: 4, text: "POS" },
      { value: 5, text: "Cheque" },
      { value: 6, text: "SISTAFE" },
      { value: 7, text: "M-Pesa Open-Api" },
      { value: 8, text: "E-Mola" },
    ],

    totalRecebido: 0,
    tranzactions: [],
    disbursedLoan: [],
  }),

  components: {
    NavBarVue,
  },

  computed: {
    ...mapGetters([
      "isLoading",
      "user",
      "token",
      "customers",
      "company",
      "updatedPassword",
      "companyLoans",
      "monthllyTransactions",
    ]),
  },

  created() {
    this.getLoans();
    this.getTranzactions();
  },

  methods: {
    // ==================== CÁLCULOS ====================

    populatePaymentReceived(loan) {
      const transactions = this.tranzactions.filter((tranz) => {
        return tranz.loanId == loan.id;
      });
      return transactions.reduce((sum, p) => sum + p.amount, 0);
    },

    convertMoney(value) {
      return MoneyFormat.formatMoney(value);
    },

    // ══════════════════════════════════════════════════════════
    //  SISTEMA FRANCÊS (PRICE) - Cálculos de Amortização
    // ══════════════════════════════════════════════════════════
    //
    //  PMT = PV × [ r × (1 + r)^n ] / [ (1 + r)^n − 1 ]
    //
    //  Onde:
    //    PMT = Valor da prestação fixa mensal
    //    PV  = Capital emprestado (principal)
    //    r   = Taxa de juros por período (mensal)
    //    n   = Número de prestações
    // ══════════════════════════════════════════════════════════

    /**
     * Calcula a prestação mensal fixa (PMT) pelo sistema francês (Price)
     */
    calculatePMT(principal, rate, n) {
      if (!principal || !n || n <= 0) return 0;
      if (rate === 0) return principal / n;

      const numerator = rate * Math.pow(1 + rate, n);
      const denominator = Math.pow(1 + rate, n) - 1;
      return principal * (numerator / denominator);
    },

    /**
     * Prestação mensal fixa (PMT) - Sistema Francês
     */
    getMonthlyInstallment(loan) {
      const P = loan.amount;
      const r = loan.interestRate;
      const n = loan.numberOfInstallments || 1;
      const pmt = this.calculatePMT(P, r, n);
      return Math.round(pmt * 100) / 100;
    },

    /**
     * Total do crédito com juros = PMT × n (Sistema Francês)
     */
    getTotalWithInterest(loan) {
      const pmt = this.getMonthlyInstallment(loan);
      const n = loan.numberOfInstallments || 1;
      return Math.round(pmt * n * 100) / 100;
    },

    /**
     * Total de juros do crédito = (PMT × n) − Capital
     */
    getTotalInterestAmount(loan) {
      return Math.round((this.getTotalWithInterest(loan) - loan.amount) * 100) / 100;
    },

    /**
     * Valor da prestação para o relatório BM (coluna 6)
     * No sistema francês, é o valor da prestação mensal fixa (PMT)
     */
    getInstallmentValue(loan) {
      return this.getMonthlyInstallment(loan);
    },

    getFirstInstallmentDate(loan) {
      // Primeira prestação: 1 mês após o desembolso
      return moment(loan.dateCreated).add(1, "M");
    },

    getLastInstallmentDate(loan) {
      // Última prestação: número de meses após o desembolso
      const n = loan.numberOfInstallments || 1;
      return moment(loan.dateCreated).add(n, "M");
    },

    formatPercentage(rate) {
      return (rate * 100).toFixed(1) + "%";
    },

    formatDate(date) {
      return moment(date).format("DD/MM/YYYY");
    },

    getRangePeriodLabel() {
      if (!this.fromDate || !this.toDate) return "";
      return moment(this.fromDate).format("DD/MM/YYYY") + " a " + moment(this.toDate).format("DD/MM/YYYY");
    },

    // ── Totais do resumo ──

    getSummaryTotalCapital() {
      return this.disbursedLoan.reduce((sum, l) => sum + l.amount, 0);
    },

    getSummaryTotalWithInterest() {
      return this.disbursedLoan.reduce((sum, l) => sum + this.getTotalWithInterest(l), 0);
    },

    getSummaryTotalMonthlyInstallment() {
      return this.disbursedLoan.reduce((sum, l) => sum + this.getMonthlyInstallment(l), 0);
    },

    getSummaryTotalInstallments() {
      return this.disbursedLoan.reduce((sum, l) => sum + (l.numberOfInstallments || 1), 0);
    },

    /**
     * Saldo devedor remanescente (Sistema Francês)
     * Total do crédito (PMT × n) − Pagamentos recebidos
     */
    getRemainingBalance(loan) {
      const totalDue = this.getTotalWithInterest(loan);
      return totalDue - this.populatePaymentReceived(loan);
    },

    /**
     * Calcula o saldo devedor do capital numa determinada prestação k
     * Fórmula: B_k = PV × (1+r)^k − PMT × [(1+r)^k − 1] / r
     * Usado para calcular o capital em dívida real
     */
    getOutstandingPrincipal(loan) {
      const P = loan.amount;
      const r = loan.interestRate;
      const n = loan.numberOfInstallments || 1;
      const pmt = this.calculatePMT(P, r, n);

      // Determinar quantas prestações foram pagas
      const totalPaid = this.populatePaymentReceived(loan);
      let paidInstallments = 0;
      if (pmt > 0) {
        paidInstallments = Math.min(Math.floor(totalPaid / pmt), n);
      }

      if (r === 0) {
        return Math.max(0, P - (pmt * paidInstallments));
      }

      // B_k = P × (1+r)^k − PMT × [(1+r)^k − 1] / r
      const k = paidInstallments;
      const factor = Math.pow(1 + r, k);
      const balance = P * factor - pmt * ((factor - 1) / r);
      return Math.max(0, Math.round(balance * 100) / 100);
    },

    getCreditoEmDivida(loan) {
      // Montante do crédito que falta pagar (total restante incluindo juros)
      const remaining = this.getRemainingBalance(loan);
      return remaining > 0 ? Math.round(remaining * 100) / 100 : 0;
    },

    getCreditoEmAtraso(loan) {
      // Montante das prestações em atraso (prestações vencidas não pagas)
      const days = this.lateDays(loan);
      if (days <= 0) return 0;

      const pmt = this.getMonthlyInstallment(loan);
      const n = loan.numberOfInstallments || 1;

      // Quantas prestações deveriam estar pagas até agora
      const monthsElapsed = moment().diff(moment(loan.dateCreated), "months");
      const installmentsDue = Math.min(monthsElapsed, n);

      // Quantas prestações foram realmente pagas
      const totalPaid = this.populatePaymentReceived(loan);
      const installmentsPaid = pmt > 0 ? Math.floor(totalPaid / pmt) : 0;

      // Prestações em atraso = prestações vencidas × PMT
      const overdueInstallments = Math.max(0, installmentsDue - installmentsPaid);
      return Math.round(overdueInstallments * pmt * 100) / 100;
    },

    lateDays(loan) {
      const diffDays = moment().diff(this.getDueDate(loan), "days");
      return diffDays >= 0 ? diffDays : 0;
    },

    latePaymentInterest(loan) {
      const diffDays = moment().diff(this.getDueDate(loan), "days");
      if (diffDays <= 0) return 0;
      // Juros de mora = saldo devedor do capital × (forfeit / 100) × dias em atraso
      const dailyRate = this.company.forfeit / 100;
      const outstandingPrincipal = this.getOutstandingPrincipal(loan);
      return Math.round(outstandingPrincipal * dailyRate * diffDays * 100) / 100;
    },

    getDueDate(loan) {
      return moment(loan.dateCreated).add(loan.numberOfInstallments || 1, "M");
    },

    getPaymentMethod(method) {
      const methods = {
        1: "Boca do Caixa",
        2: "Depósito Bancário",
        3: "Transferência Bancária",
        4: "POS",
        5: "Cheque",
        6: "SISTAFE",
        7: "M-Pesa Open-Api",
        8: "E-Mola",
      };
      return methods[method] || "";
    },

    getRate(rate) {
      return rate * 100 + "%";
    },

    getReportPeriodLabel() {
      if (!this.fromDate || !this.toDate) {
        return moment(this.fromDate).format("MMMM [de] YYYY");
      }
      return moment(this.fromDate).format("DD/MM/YYYY") + " a " + moment(this.toDate).format("DD/MM/YYYY");
    },

    // ==================== TOTAIS (Relatório BM) ====================

    getTotalDesembolsado() {
      return this.disbursedLoan.reduce((sum, p) => sum + p.amount, 0);
    },

    getTotalPrestacao() {
      // Total das prestações mensais (PMT de cada crédito)
      return this.disbursedLoan.reduce((sum, p) => sum + this.getMonthlyInstallment(p), 0);
    },

    getTotalDivida() {
      return this.disbursedLoan.reduce((sum, p) => sum + this.getCreditoEmDivida(p), 0);
    },

    getTotalAtraso() {
      return this.disbursedLoan.reduce((sum, p) => sum + this.getCreditoEmAtraso(p), 0);
    },

    getTotal() {
      return this.disbursedLoan.reduce((sum, p) => sum + p.amount, 0);
    },

    getRateAmount() {
      // Total de juros de todos os créditos (Sistema Francês)
      return this.disbursedLoan.reduce(
        (sum, p) => sum + this.getTotalInterestAmount(p),
        0
      );
    },

    // ==================== DADOS ====================

    refreshData() {
      this.getLoans();
      this.getTranzactions();
    },

    getTranzactions() {
      this.$store.commit("LOADING_STATUS", true);
      const queryString = `?from=${this.fromDate}&to=${this.toDate}&companyId=${
        this.company.id
      }`;
      axios
        .get(`/api/tranzaction/${queryString}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            // Filtrar transacções pelo intervalo de datas no frontend como fallback
            const from = moment(this.fromDate).startOf("day");
            const to = moment(this.toDate).endOf("day");
            this.tranzactions = data.result.filter((t) => {
              const tDate = moment(t.createdAt);
              return tDate.isSameOrAfter(from) && tDate.isSameOrBefore(to);
            });
          } else {
            this.showToast("Aviso", "warning", "Reembolsos indisponíveis.");
            this.tranzactions = [];
          }
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
          this.tranzactions = [];
        });
    },

    getLoans() {
      const from = moment(this.fromDate).startOf("day");
      const to = moment(this.toDate).endOf("day");

      this.disbursedLoan = this.companyLoans.filter((credit) => {
        const creditDate = moment(credit.dateCreated);
        return (
          creditDate.isSameOrAfter(from) &&
          creditDate.isSameOrBefore(to) &&
          credit.status == 1
        );
      });
    },

    getCustomerDetails(accountNumber) {
      const filteredCustomer = this.customers.filter((a) => {
        return a.accountNumber == accountNumber;
      });
      return filteredCustomer[0] || { customerName: "N/A" };
    },

    calculateTotalCollected() {
      return MoneyFormat.calculateSumOfArray(this.tranzactions);
    },

    // ==================== EXPORTAR EXCEL (PAGAMENTOS) ====================

    async generatePaymentExcel() {
      const DATA_ROWS = [];
      let i = 0;
      for (let row of this.tranzactions) {
        const dataValues = {
          "#": i + 1,
          "Nome do cliente": this.getCustomerDetails(row.accountNumber)
            .customerName,
          "Data de pagamento": DateFormat.formatDate(row.createdAt),
          "Método de Pgt": this.getPaymentMethod(row.paymentMethod),
          "Referência": row.tranzactionReference,
          "Total pago": this.convertMoney(row.amount),
          "Técnico": row.staffName,
        };
        i++;
        DATA_ROWS.push(dataValues);
      }

      const workSheet = XLSX.utils.json_to_sheet(DATA_ROWS);
      const workBook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workBook, workSheet, "Pagamentos");
      const rangeLabel = `${this.fromDate}_a_${this.toDate}`;
      XLSX.writeFile(workBook, `Pagamentos_${rangeLabel}.xlsx`);
    },

    // ==================== EXPORTAR EXCEL (RELATÓRIO BM) ====================

    async generateExcelReport() {
      const period = `${this.fromDate}_a_${this.toDate}`;

      // --- Folha principal: Relatório ---
      const headerRow = [
        "Nº da Operação (1)",
        "Nome do Cliente (2)",
        "Data de Desembolso (3)",
        "Montante de Desembolso (4)",
        "Finalidade do Crédito (5)",
        "Valor da Prestação (6)",
        "Periodicidade dos Pagamentos (7)",
        "Prazo de Reembolso (8)",
        "Taxa de Juro (9)",
        "Crédito em Dívida (10)",
        "Crédito em Atraso (11)",
        "Dias em Atraso (12)",
        "PPEs (13)",
      ];

      const dataRows = this.disbursedLoan.map((loan) => {
        const customer = this.getCustomerDetails(loan.accountNumber);
        return [
          loan.id,
          customer.customerName,
          DateFormat.formatDate(loan.dateCreated),
          loan.amount,
          "Comércio",
          this.getInstallmentValue(loan),
          "Mensal",
          DateFormat.formatDate(this.getDueDate(loan)),
          this.getRate(loan.interestRate),
          this.getCreditoEmDivida(loan),
          this.getCreditoEmAtraso(loan),
          this.lateDays(loan) > 0 ? this.lateDays(loan) : "",
          "",
        ];
      });

      // Linha de totais
      const totalsRow = [
        "",
        "",
        "Total",
        this.getTotalDesembolsado(),
        "",
        this.getTotalPrestacao(),
        "",
        "",
        "",
        this.getTotalDivida(),
        this.getTotalAtraso(),
        "",
        "",
      ];

      const allRows = [headerRow, ...dataRows, [], totalsRow];
      const ws = XLSX.utils.aoa_to_sheet(allRows);

      // Definir larguras das colunas
      ws["!cols"] = [
        { wch: 16 },  // Nº Operação
        { wch: 28 },  // Nome
        { wch: 18 },  // Data Desembolso
        { wch: 22 },  // Montante
        { wch: 18 },  // Finalidade
        { wch: 20 },  // Prestação
        { wch: 22 },  // Periodicidade
        { wch: 18 },  // Prazo
        { wch: 14 },  // Taxa
        { wch: 20 },  // Dívida
        { wch: 20 },  // Atraso
        { wch: 16 },  // Dias
        { wch: 10 },  // PPEs
      ];

      // Formatar colunas numéricas (Montante, Prestação, Dívida, Atraso)
      const numericCols = [3, 5, 9, 10]; // D, F, J, K (0-indexed)
      for (let r = 1; r <= dataRows.length; r++) {
        numericCols.forEach((c) => {
          const cellRef = XLSX.utils.encode_cell({ r: r, c: c });
          if (ws[cellRef] && typeof ws[cellRef].v === "number") {
            ws[cellRef].z = "#,##0.00";
          }
        });
      }
      // Formatar totais
      const totalsRowIdx = dataRows.length + 2;
      numericCols.forEach((c) => {
        const cellRef = XLSX.utils.encode_cell({ r: totalsRowIdx, c: c });
        if (ws[cellRef] && typeof ws[cellRef].v === "number") {
          ws[cellRef].z = "#,##0.00";
        }
      });

      // --- Folha de notas explicativas ---
      const notesData = [
        ["Notas Explicativas"],
        [],
        ["1 - Número da operação de crédito"],
        ["2 - Nome do cliente"],
        ["3 - Data do desembolso inicial"],
        ["4 - Valor do crédito concedido"],
        ["5 - Finalidade de crédito desembolsado, designadamente para empresas, consumo ou habitação"],
        ["6 - Montante da prestação periódica para amortizar o crédito"],
        ["7 - Forma de pagamento acordada, designadamente diária, semanal, mensal ou anual"],
        ["8 - Data de vencimento do crédito desembolsado"],
        ["9 - Percentagem da taxa de juro aplicada a crédito"],
        ["10 - Montante do crédito desembolsado que falta pagar, excluindo prestações em atraso"],
        ["11 - Montante das prestações em atraso incluindo capital e juros"],
        ["12 - Dias em atraso do pagamento das prestações"],
        ["13 - Crédito concedido a pessoas politicamente expostas"],
      ];
      const wsNotes = XLSX.utils.aoa_to_sheet(notesData);
      wsNotes["!cols"] = [{ wch: 80 }];

      // Criar workbook
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, `Relatório ${period}`.substring(0, 31));
      XLSX.utils.book_append_sheet(wb, wsNotes, "Notas Explicativas");

      XLSX.writeFile(wb, `Relatorio_BM_${period}.xlsx`);
    },

    // ==================== EXPORTAR PDF (RELATÓRIO BM) ====================

    async generatePDFReport() {
      const period = `${this.fromDate} a ${this.toDate}`;

      // Construir linhas da tabela
      const body = [];
      for (let row of this.disbursedLoan) {
        const customer = this.getCustomerDetails(row.accountNumber);
        body.push([
          { text: row.id, fontSize: 7, alignment: "center" },
          { text: customer.customerName, fontSize: 7 },
          { text: DateFormat.formatDate(row.dateCreated), fontSize: 7, alignment: "center" },
          { text: MoneyFormat.formatMoney(row.amount), fontSize: 7, alignment: "right" },
          { text: "Comércio", fontSize: 7, alignment: "center" },
          { text: MoneyFormat.formatMoney(this.getInstallmentValue(row)), fontSize: 7, alignment: "right" },
          { text: "Mensal", fontSize: 7, alignment: "center" },
          { text: DateFormat.formatDate(this.getDueDate(row)), fontSize: 7, alignment: "center" },
          { text: this.getRate(row.interestRate), fontSize: 7, alignment: "center" },
          { text: MoneyFormat.formatMoney(this.getCreditoEmDivida(row)), fontSize: 7, alignment: "right" },
          { text: this.getCreditoEmAtraso(row) > 0 ? MoneyFormat.formatMoney(this.getCreditoEmAtraso(row)) : "", fontSize: 7, alignment: "right" },
          { text: this.lateDays(row) > 0 ? this.lateDays(row).toString() : "", fontSize: 7, alignment: "center" },
          { text: "", fontSize: 7 },
        ]);
      }

      // Linha de totais
      body.push([
        { text: "", fontSize: 7 },
        { text: "", fontSize: 7 },
        { text: "Total", fontSize: 7, bold: true, alignment: "right" },
        { text: MoneyFormat.formatMoney(this.getTotalDesembolsado()), fontSize: 7, bold: true, alignment: "right", fillColor: "#dc3545", color: "#ffffff" },
        { text: "", fontSize: 7 },
        { text: MoneyFormat.formatMoney(this.getTotalPrestacao()), fontSize: 7, bold: true, alignment: "right", fillColor: "#dc3545", color: "#ffffff" },
        { text: "", fontSize: 7 },
        { text: "", fontSize: 7 },
        { text: "", fontSize: 7 },
        { text: MoneyFormat.formatMoney(this.getTotalDivida()), fontSize: 7, bold: true, alignment: "right" },
        { text: MoneyFormat.formatMoney(this.getTotalAtraso()), fontSize: 7, bold: true, alignment: "right" },
        { text: "", fontSize: 7 },
        { text: "", fontSize: 7 },
      ]);

      // Notas explicativas
      const notesText = [
        "1 - Número da operação de crédito",
        "2 - Nome do cliente",
        "3 - Data do desembolso inicial",
        "4 - Valor do crédito concedido",
        "5 - Finalidade de crédito desembolsado, designadamente para empresas, consumo ou habitação",
        "6 - Montante da prestação periódica para amortizar o crédito",
        "7 - Forma de pagamento acordada, designadamente diária, semanal, mensal ou anual",
        "8 - Data de vencimento do crédito desembolsado",
        "9 - Percentagem da taxa de juro aplicada a crédito",
        "10 - Montante do crédito desembolsado que falta pagar, excluindo prestações em atraso",
        "11 - Montante das prestações em atraso incluindo capital e juros",
        "12 - Dias em atraso do pagamento das prestações",
        "13 - Crédito concedido a pessoas politicamente expostas",
      ].join("\n");

      let docDefinition = {
        pageOrientation: "landscape",
        pageMargins: [20, 30, 20, 30],
        content: [
          // Cabeçalho BM
          {
            columns: [
              {
                image: bmLogo.getBMLogo(),
                width: 70,
              },
              {
                text: "BANCO DE MOÇAMBIQUE\nDEPARTAMENTO DE SUPERVISÃO PRUDENCIAL\nREPORTE PERIÓDICO DE INFORMAÇÕES DE MICROFINANÇAS\nINSTITUIÇÕES SUJEITAS À MONITORIZAÇÃO",
                fontSize: 9,
                alignment: "center",
                bold: true,
                margin: [0, 10, 0, 0],
              },
            ],
          },
          { text: "\n" },

          // Período
          {
            text: `PERÍODO DE REPORTE: ${period}`,
            fontSize: 9,
            bold: true,
            alignment: "left",
          },
          { text: "\n" },

          // Identificação da instituição
          {
            text: "1. IDENTIFICAÇÃO DA INSTITUIÇÃO",
            fontSize: 9,
            bold: true,
          },
          {
            text: `Denominação: ${this.company.companyName}\nEndereço: ${this.company.companyAddress}\nTelefone: ${this.company.companyPhone}\nE-mail: ${this.company.companyEmail}\nResponsável pela Gestão: ${this.company.companyManager}`,
            fontSize: 8,
            margin: [10, 5, 0, 0],
          },
          { text: "\n" },

          // Tabela principal
          {
            text: "2. CRÉDITOS DESEMBOLSADOS",
            fontSize: 9,
            bold: true,
          },
          { text: "\n" },
          {
            table: {
              headerRows: 1,
              widths: [
                "auto", "*", "auto", "auto", "auto", "auto", "auto", "auto", "auto", "auto", "auto", "auto", "auto",
              ],
              body: [
                [
                  { text: "Nº Op. (1)", style: "columnsTitle" },
                  { text: "Nome do Cliente (2)", style: "columnsTitle" },
                  { text: "Data (3)", style: "columnsTitle" },
                  { text: "Montante (4)", style: "columnsTitle" },
                  { text: "Finalidade (5)", style: "columnsTitle" },
                  { text: "Prestação (6)", style: "columnsTitle" },
                  { text: "Period. (7)", style: "columnsTitle" },
                  { text: "Prazo (8)", style: "columnsTitle" },
                  { text: "Juros (9)", style: "columnsTitle" },
                  { text: "Dívida (10)", style: "columnsTitle" },
                  { text: "Atraso (11)", style: "columnsTitle" },
                  { text: "Dias (12)", style: "columnsTitle" },
                  { text: "PPEs (13)", style: "columnsTitle" },
                ],
                ...body,
              ],
            },
            layout: {
              hLineWidth: function () {
                return 0.5;
              },
              vLineWidth: function () {
                return 0.5;
              },
              hLineColor: function () {
                return "#aaaaaa";
              },
              vLineColor: function () {
                return "#aaaaaa";
              },
              fillColor: function (rowIndex) {
                if (rowIndex === 0) return "#333333";
                return null;
              },
            },
          },
          { text: "\n\n" },

          // Notas explicativas
          {
            text: "Notas Explicativas",
            fontSize: 9,
            bold: true,
          },
          {
            text: notesText,
            fontSize: 7,
            margin: [0, 5, 0, 0],
            lineHeight: 1.4,
          },
        ],
        styles: {
          columnsTitle: {
            fontSize: 7,
            bold: true,
            color: "#ffffff",
            alignment: "center",
          },
        },
        footer: function (currentPage, pageCount) {
          return {
            text: `Página ${currentPage} de ${pageCount}`,
            alignment: "center",
            fontSize: 7,
            margin: [0, 10, 0, 0],
          };
        },
      };

      pdfMake.createPdf(docDefinition).open();
    },

    // ==================== UTILITÁRIOS ====================

    showToast(title, variant, msg) {
      this.$bvToast.toast(`${msg}`, {
        title,
        variant,
        solid: true,
        toaster: "b-toaster-top-center",
        autoHideDelay: 5000,
      });
    },
  },
};
</script>

